    // =========================================================================
    // Write FSM  — m_wdata/m_wstrb/m_wlast/wr_data_ready are combinational
    // =========================================================================
    localparam [2:0] WR_IDLE=3'd0, WR_ADDR=3'd1, WR_DATA=3'd2, WR_RESP=3'd3, WR_DONE=3'd4;
    reg [2:0] wr_state;
    reg [7:0] wr_beat_cnt;
    reg [7:0] wr_len_lat;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wr_state    <= WR_IDLE;
            m_awvalid   <= 1'b0;
            m_awid      <= {ID_WIDTH{1'b0}};
            m_awaddr    <= {ADDR_WIDTH{1'b0}};
            m_awlen     <= 8'd0;
            m_wvalid    <= 1'b0;
            m_bready    <= 1'b0;
            wr_beat_cnt <= 8'd0;
            wr_len_lat  <= 8'd0;
            wr_done     <= 1'b0;
            wr_error    <= 1'b0;
        end else begin
            wr_done <= 1'b0;
            case (wr_state)
                WR_IDLE: begin
                    m_awvalid <= 1'b0;
                    m_wvalid  <= 1'b0;
                    if (wr_start) begin
                        m_awid      <= {ID_WIDTH{1'b0}};
                        m_awaddr    <= wr_addr;
                        m_awlen     <= wr_len - 8'd1;
                        wr_len_lat  <= wr_len;
                        m_awvalid   <= 1'b1;
                        wr_beat_cnt <= 8'd0;
                        wr_error    <= 1'b0;
                        wr_state    <= WR_ADDR;
                    end
                end
                WR_ADDR: begin
                    if (m_awvalid && m_awready) begin
                        m_awvalid <= 1'b0;
                        m_wvalid  <= 1'b1;
                        wr_state  <= WR_DATA;
                    end
                end
                WR_DATA: begin
                    if (m_wvalid && m_wready) begin
                        if (wr_beat_cnt == wr_len_lat - 8'd1) begin
                            m_wvalid <= 1'b0;
                            m_bready <= 1'b1;
                            wr_state <= WR_RESP;
                        end else begin
                            wr_beat_cnt <= wr_beat_cnt + 8'd1;
                        end
                    end
                end
                WR_RESP: begin
                    if (m_bvalid && m_bready) begin
                        m_bready <= 1'b0;
                        if (m_bresp != 2'b00) wr_error <= 1'b1;
                        wr_state <= WR_DONE;
                    end
                end
                WR_DONE: begin
                    wr_done  <= 1'b1;
                    wr_state <= WR_IDLE;
                end
                default: wr_state <= WR_IDLE;
            endcase
        end
    end

    assign m_wdata        = wr_data;
    assign m_wstrb         = wr_strb;
    assign m_wlast         = (wr_state == WR_DATA) && (wr_beat_cnt == wr_len_lat - 8'd1);
    assign wr_data_ready   = (wr_state == WR_DATA) && m_wvalid && m_wready;

endmodule
